    jmp  main

#addr 0x0200
clear:
    ; video RAM 6000-FFFF = 0, then mode byte = [mode] for rows 4A20-4BFF
    ld   0x60, ac
    ld   ac, [0x38]
clr_pg:
    ld   [0x38], y
    clr  x
clr_b:
    ld   0x00, [y,x]
    ld   x, ac
    inc
    ld   ac, x
    bne  clr_b
    ld   [0x38], ac
    inc
    ld   ac, [0x38]
    bne  clr_pg
    ld   0x4A, y
    ld   0x20, x
mode0:
    ld   [0x37], ac
    ld   ac, [y,x]
    ld   x, ac
    inc
    ld   ac, x
    bne  mode0
    ld   0x4B, y
mode1:
    ld   [0x37], ac
    ld   ac, [y,x]
    ld   x, ac
    inc
    ld   ac, x
    bne  mode1
    ld   [0x2D], y
    jmp  [0x2C]

#addr 0x0300
delay:
    ; about 5 s at 25.175 MHz, less the video stalls
    ld   0xC1, ac
    ld   ac, [0x3A]
dly3:
    ld   0x00, ac
    ld   ac, [0x39]
dly2:
    clr  ac
dly1:
    nop
    dec
    bne  dly1
    ld   [0x39], ac
    dec
    ld   ac, [0x39]
    bne  dly2
    ld   [0x3A], ac
    dec
    ld   ac, [0x3A]
    bne  dly3
    ld   [0x2D], y
    jmp  [0x2C]

#addr 0x0400
pass0:
