    jmp  tstart
ret_14:
    ld   0x00, ac
    ld   ac, [0x2B]
    ld   0x62, ac
    ld   ac, [0x35]
    ; cx = -2.0 = -512 = (hi -4, lo 0)
    ld   0xFC, ac
    ld   ac, [0x2F]
    ld   0x00, ac
    ld   ac, [0x2E]
    ld   0x4F, ac
    ld   ac, [0x36]
col0:
    ld   [0x35], ac
    ld   ac, [0x34]
    ld   0x20, ac
    ld   ac, [0x33]
    ; cy = -240/256 = (hi -2, lo 16)
    ld   0xFE, ac
    ld   ac, [0x29]
    ld   0x10, ac
    ld   ac, [0x28]
row0:
    ld   [0x2E], ac
    ld   ac, [0x26]
    ld   [0x2F], ac
    ld   ac, [0x27]
    ld   0x00, ac
    ld   ac, [0x30]
    ld   0x08, ac
    ld   ac, [0x32]
pt0:
    ld   ret_15, ac
    ld   ac, [0x2C]
    ld   ret_15 >> 8, ac
    ld   ac, [0x2D]
    ld   kernel >> 8, y
    jmp  kernel
ret_15:
    ld   ac, [0x31]
    ld   [0x30], ac
    shr  ac
    or   [0x31], ac
    ld   ac, [0x30]
    ; next point: cx lo is a multiple of 8 plus < 8, never carries
    ld   [0x26], ac
    add  1, ac
    ld   ac, [0x26]
    ld   [0x32], ac
    dec
    ld   ac, [0x32]
    bne  pt0
    ; write the byte to 1 screen row(s)
    ld   [0x30], ac
    ld   [0x33], x
    ld   [0x34], y
    ld   ac, [y,x]
    ld   x, ac
    inc
    ld   ac, x
    ld   ac, [0x33]
    bne  nw0
    ld   [0x34], ac
    inc
    ld   ac, [0x34]
nw0:
    ; once per byte: check the line read for a new frame
    ld   ret_16, ac
    ld   ac, [0x43]
    ld   ret_16 >> 8, ac
    ld   ac, [0x44]
    ld   poll >> 8, y
    jmp  poll
ret_16:
    ; cy += 1/256
    ld   [0x28], ac
    add  1, ac
    bge  cyok0
    and  0x7F, ac
    ld   ac, [0x28]
    ld   [0x29], ac
    inc
    ld   ac, [0x29]
    bra  cyd0
cyok0:
    ld   ac, [0x28]
cyd0:
    ; column done after 480 rows: rowy = vpage + 2
    ld   [0x34], ac
    sub  [0x35], ac
    sub  2, ac
    beq  cdone0
    ld   row0 >> 8, y
    jmp  row0
cdone0:
    ; next byte column: cx0 += 8/256, video page += 2
    ld   [0x2E], ac
    add  8, ac
    bge  cxok0
    and  0x7F, ac
    ld   ac, [0x2E]
    ld   [0x2F], ac
    inc
    ld   ac, [0x2F]
    bra  cxd0
cxok0:
