cxd0:
    ld   [0x35], ac
    add  2, ac
    ld   ac, [0x35]
    ld   [0x36], ac
    dec
    ld   ac, [0x36]
    beq  pdone0
    ld   col0 >> 8, y
    jmp  col0
pdone0:
    ld   [0x3C], y
    jmp  [0x3B]

#addr 0x0500
