cyd3:
    ; column done after 480 rows: rowy = vpage + 2
    ld   [0x34], ac
    sub  [0x35], ac
    sub  2, ac
    beq  cdone3
    ld   row3 >> 8, y
    jmp  row3
cdone3:
    ; next byte column: cx0 += 8/256, video page += 2
    ld   [0x2E], ac
    add  8, ac
    bge  cxok3
    and  0x7F, ac
    ld   ac, [0x2E]
    ld   [0x2F], ac
    inc
    ld   ac, [0x2F]
    bra  cxd3
cxok3:
    ld   ac, [0x2E]
cxd3:
    ld   [0x35], ac
    add  2, ac
    ld   ac, [0x35]
    ld   [0x36], ac
    dec
    ld   ac, [0x36]
    beq  pdone3
    ld   col3 >> 8, y
    jmp  col3
pdone3:
    ld   [0x3C], y
    jmp  [0x3B]

#addr 0x0800
poll:
    ; read the line read (V9:V2, 124-255) and add one frame to the timer
    ; when it went down.  cur - last - 96 >= 0 means it wrapped, as long as
    ; polls are less than 95 steps (380 lines) apart.  Uses y and x.
    ld   0x50, y
    ld   [y,x], ac
    ld   ac, [0x3D]
    sub  [0x3E], ac
    sub  96, ac
    blt  pnw
    ld   0x01, ac
    ld   ac, [0x3F]
    ld   0x10, ac
    ld   ac, [0x40]
    ld   ret_29, ac
    ld   ac, [0x45]
    ld   ret_29 >> 8, ac
    ld   ac, [0x46]
    ld   dadd >> 8, y
    jmp  dadd
ret_29:
pnw:
    ld   [0x3D], ac
    ld   ac, [0x3E]
    ld   [0x44], y
    jmp  [0x43]

#addr 0x0900
dadd:
    ; timer digits at 0x50 += addend digits at 0x50 + [doff], decimal
    clr  ac
    ld   ac, [0x41]
    ld   0x50, x
dl:
    ld   [x], ac
    add  [0x41], ac
    ld   ac, [0x42]
    ld   x, ac
    add  [0x40], ac
    ld   ac, x
    ld   [x], ac
    add  [0x42], ac
    ld   ac, [0x42]
    ld   x, ac
    sub  [0x40], ac
    ld   ac, x
    ld   [0x42], ac
    sub  10, ac
    blt  dlt
    ld   ac, [x]
    ld   1, ac
    bra  dn
dlt:
    ld   [0x42], ac
    ld   ac, [x]
    clr  ac
dn:
    ld   ac, [0x41]
    ld   x, ac
    inc
    ld   ac, x
    sub  0x59, ac
    bne  dl
    ld   [0x46], y
    jmp  [0x45]

#addr 0x0A00
tstart:
    ; start the timer at the top of a frame: wait for the line read to wrap
    ld   ret_30, ac
    ld   ac, [0x43]
    ld   ret_30 >> 8, ac
    ld   ac, [0x44]
    ld   poll >> 8, y
    jmp  poll
ret_30:
sync:
    ld   0x00, ac
    ld   ac, [0x3F]
    ld   ret_31, ac
    ld   ac, [0x43]
    ld   ret_31 >> 8, ac
    ld   ac, [0x44]
    ld   poll >> 8, y
    jmp  poll
ret_31:
    ld   [0x3F], ac
    beq  sync
    ld   ret_32, ac
    ld   ac, [0x43]
    ld   ret_32 >> 8, ac
    ld   ac, [0x44]
    ld   tclear >> 8, y
    jmp  tclear
ret_32:
    ld   [0x2D], y
    jmp  [0x2C]

#addr 0x0B00
tclear:
    ; timer = 0, frame addend = 16800 us, step addend = 128 us
    ld   0x50, x
tcl:
    ld   0x00, [x]
    ld   x, ac
    inc
    ld   ac, x
    sub  0x79, ac
    bne  tcl
    ld   8, ac
    ld   ac, [0x62]
    ld   6, ac
    ld   ac, [0x63]
    ld   1, ac
    ld   ac, [0x64]
    ld   8, ac
    ld   ac, [0x70]
    ld   2, ac
    ld   ac, [0x71]
    ld   1, ac
    ld   ac, [0x72]
    ld   [0x44], y
    jmp  [0x43]

#addr 0x0C00
tshow:
    ; stop the timer: whole frames are counted, add the 128 us steps since
    ; the top of this frame
    ld   ret_33, ac
    ld   ac, [0x43]
    ld   ret_33 >> 8, ac
    ld   ac, [0x44]
    ld   poll >> 8, y
    jmp  poll
ret_33:
    ld   [0x3E], ac
    sub  124, ac
    ld   ac, [0x38]
    ld   0x20, ac
    ld   ac, [0x40]
part:
    ld   [0x38], ac
    beq  pdn
    dec
    ld   ac, [0x38]
    ld   ret_34, ac
    ld   ac, [0x45]
    ld   ret_34 >> 8, ac
    ld   ac, [0x46]
    ld   dadd >> 8, y
    jmp  dadd
ret_34:
    bra  part
pdn:
    ; a black 1 bpp band, screen rows 232-247: mode bytes 0, pixels 0
    ld   0x61, ac
    ld   ac, [0x38]
bnd:
    ld   [0x38], y
    ld   0x08, x
bndr:
    ld   0x00, [y,x]
    ld   x, ac
    inc
    ld   ac, x
    sub  0x18, ac
    bne  bndr
    ld   [0x38], ac
    add  2, ac
    ld   ac, [0x38]
    sub  0x01, ac
    bne  bnd
    ld   0x4B, y
    ld   0x08, x
bndm:
    ld   0x00, [y,x]
    ld   x, ac
    inc
    ld   ac, x
    sub  0x18, ac
    bne  bndm
    ld   tshow2 >> 8, y
    jmp  tshow2

#addr 0x0D00
tshow2:
    ; "SSS.SSS s", leading zeros of the seconds as spaces
    ld   0xA9, ac
    ld   ac, [0x4C]
    ld   0x0C, ac
    ld   ac, [0x4D]
    ld   [0x58], ac
    bne  sh1
    ld   11, ac
    ld   ac, [0x58]
    ld   [0x57], ac
    bne  sh1
    ld   11, ac
    ld   ac, [0x57]
sh1:
    ld   0x58, ac
    ld   ac, [0x49]
shlp:
    ld   [0x49], x
    ld   [x], ac
    ld   ac, [0x4E]
    ld   ret_35, ac
    ld   ac, [0x47]
    ld   ret_35 >> 8, ac
    ld   ac, [0x48]
    ld   gdraw >> 8, y
    jmp  gdraw
ret_35:
    ld   [0x49], ac
    sub  0x56, ac
    bne  shnd
    ld   0x0A, ac
    ld   ac, [0x4E]
    ld   ret_36, ac
    ld   ac, [0x47]
    ld   ret_36 >> 8, ac
    ld   ac, [0x48]
    ld   gdraw >> 8, y
    jmp  gdraw
ret_36:
shnd:
    ld   [0x49], ac
    dec
    ld   ac, [0x49]
    sub  0x52, ac
    bne  shlp
    ld   0x0B, ac
    ld   ac, [0x4E]
    ld   ret_37, ac
    ld   ac, [0x47]
    ld   ret_37 >> 8, ac
    ld   ac, [0x48]
    ld   gdraw >> 8, y
    jmp  gdraw
ret_37:
    ld   0x0C, ac
    ld   ac, [0x4E]
    ld   ret_38, ac
    ld   ac, [0x47]
    ld   ret_38 >> 8, ac
    ld   ac, [0x48]
    ld   gdraw >> 8, y
    jmp  gdraw
ret_38:
    ld   [0x2D], y
    jmp  [0x2C]

#addr 0x0E00
gdraw:
    ; draw glyph [dig] at page [cpg], row byte [crow]; then cpg += 2
    ld   [0x4E], ac
    shl
    shl
    shl
    add  0x80, ac
    ld   ac, [0x4A]
    ld   [0x4D], ac
    ld   ac, [0x4B]
    ld   [0x4A], x
    ld   [x], ac
    ld   ac, [0x38]
    ld   [0x4B], x
    ld   [0x4C], y
    ld   [0x38], ac
    ld   ac, [y,x]
    ld   [0x4A], ac
    inc
    ld   ac, [0x4A]
    ld   x, ac
    inc
    ld   ac, [0x4B]
    ld   [0x4A], x
    ld   [x], ac
    ld   ac, [0x38]
    ld   [0x4B], x
    ld   [0x4C], y
    ld   [0x38], ac
    ld   ac, [y,x]
    ld   [0x4A], ac
    inc
    ld   ac, [0x4A]
    ld   x, ac
    inc
    ld   ac, [0x4B]
    ld   [0x4A], x
    ld   [x], ac
    ld   ac, [0x38]
    ld   [0x4B], x
    ld   [0x4C], y
    ld   [0x38], ac
    ld   ac, [y,x]
    ld   [0x4A], ac
    inc
    ld   ac, [0x4A]
    ld   x, ac
    inc
    ld   ac, [0x4B]
    ld   [0x4A], x
    ld   [x], ac
    ld   ac, [0x38]
    ld   [0x4B], x
    ld   [0x4C], y
    ld   [0x38], ac
    ld   ac, [y,x]
    ld   [0x4A], ac
    inc
    ld   ac, [0x4A]
    ld   x, ac
    inc
    ld   ac, [0x4B]
    ld   [0x4A], x
    ld   [x], ac
    ld   ac, [0x38]
    ld   [0x4B], x
    ld   [0x4C], y
    ld   [0x38], ac
    ld   ac, [y,x]
    ld   [0x4A], ac
    inc
    ld   ac, [0x4A]
    ld   x, ac
    inc
    ld   ac, [0x4B]
    ld   [0x4A], x
    ld   [x], ac
    ld   ac, [0x38]
    ld   [0x4B], x
    ld   [0x4C], y
    ld   [0x38], ac
    ld   ac, [y,x]
    ld   [0x4A], ac
    inc
    ld   ac, [0x4A]
    ld   x, ac
    inc
    ld   ac, [0x4B]
    ld   [0x4A], x
    ld   [x], ac
    ld   ac, [0x38]
    ld   [0x4B], x
    ld   [0x4C], y
    ld   [0x38], ac
    ld   ac, [y,x]
    ld   [0x4A], ac
    inc
    ld   ac, [0x4A]
    ld   x, ac
    inc
    ld   ac, [0x4B]
    ld   [0x4A], x
    ld   [x], ac
    ld   ac, [0x38]
    ld   [0x4B], x
    ld   [0x4C], y
    ld   [0x38], ac
    ld   ac, [y,x]
    ld   [0x4C], ac
    add  2, ac
    ld   ac, [0x4C]
    ld   [0x48], y
    jmp  [0x47]

#addr 0x0F00
kernel:
    ; in: cx, cy, coff.  out: AC = color for this mode.  returns to [reth, ret]
    clr  ac
    ld   ac, [0x10]
    ld   ac, [0x11]
    ld   ac, [0x13]
    ld   ac, [0x14]
    ld   ac, [0x12]
    ld   ac, [0x15]
    ld   0x20, ac
    ld   ac, [0x2A]
iter:
    ; x*x, y*y
    ld   [0x10], x
    ld   [0x11], ac
    add  0x20, y
    ld   [y,x], ac
    ld   ac, [0x16]
    ld   [0x11], ac
    add  0x28, y
    ld   [y,x], ac
    ld   ac, [0x17]
    ld   [0x13], x
    ld   [0x14], ac
    add  0x20, y
    ld   [y,x], ac
    ld   ac, [0x18]
    ld   [0x14], ac
    add  0x28, y
    ld   [y,x], ac
    ld   ac, [0x19]
    ; t = x*x + y*y, escape if t >= 4.0 (hi >= 8)
    ld   [0x16], ac
    add  [0x18], ac
    bge  nc_39
    and  0x7F, ac
    ld   ac, [0x1A]
    ld   [0x17], ac
    add  [0x19], ac
    inc
    bra  ad_40
nc_39:
    ld   ac, [0x1A]
    ld   [0x17], ac
    add  [0x19], ac
ad_40:
    ld   ac, [0x1B]
    sub  8, ac
    bge  escape
    ; x' = x*x - y*y + cx
    ld   [0x16], ac
    sub  [0x18], ac
    bge  nb_41
    and  0x7F, ac
    ld   ac, [0x1C]
    ld   [0x17], ac
    sub  [0x19], ac
    dec
    bra  sd_42
nb_41:
    ld   ac, [0x1C]
    ld   [0x17], ac
    sub  [0x19], ac
sd_42:
    ld   ac, [0x1D]
    ld   [0x1C], ac
    add  [0x26], ac
    bge  nc_43
    and  0x7F, ac
    ld   ac, [0x1E]
    ld   [0x1D], ac
    add  [0x27], ac
    inc
    bra  ad_44
nc_43:
    ld   ac, [0x1E]
    ld   [0x1D], ac
    add  [0x27], ac
ad_44:
    ld   ac, [0x1F]
    ld   kernel2 >> 8, y
    jmp  kernel2
escape:
    ; color from the iterations left (0 = never escaped)
    ld   [0x2A], ac
    add  [0x2B], ac
    ld   ac, x
    ld   0x1F, y
    ld   [y,x], ac
    ld   [0x2D], y
    jmp  [0x2C]

#addr 0x1000
kernel2:
    ; s = |x + y|
    ld   [0x12], ac
    xor  [0x15], ac
    bne  sdiff
    ld   [0x10], ac
    add  [0x13], ac
    bge  nc_45
    and  0x7F, ac
    ld   ac, [0x22]
    ld   [0x11], ac
    add  [0x14], ac
    inc
    bra  ad_46
nc_45:
    ld   ac, [0x22]
    ld   [0x11], ac
    add  [0x14], ac
ad_46:
    ld   ac, [0x23]
    bra  sdone
sdiff:
    ld   [0x10], ac
    sub  [0x13], ac
    bge  nb_47
    and  0x7F, ac
    ld   ac, [0x22]
    ld   [0x11], ac
    sub  [0x14], ac
    dec
    bra  sd_48
nb_47:
    ld   ac, [0x22]
    ld   [0x11], ac
    sub  [0x14], ac
sd_48:
    ld   ac, [0x23]
    bge  sdone
    ld   [0x13], ac
    sub  [0x10], ac
    bge  nb_49
    and  0x7F, ac
    ld   ac, [0x22]
    ld   [0x14], ac
    sub  [0x11], ac
    dec
    bra  sd_50
nb_49:
    ld   ac, [0x22]
    ld   [0x14], ac
    sub  [0x11], ac
sd_50:
    ld   ac, [0x23]
sdone:
    ld   [0x22], x
    ld   [0x23], ac
    add  0x20, y
    ld   [y,x], ac
    ld   ac, [0x24]
    ld   [0x23], ac
    add  0x28, y
    ld   [y,x], ac
    ld   ac, [0x25]
    ; y' = s*s - t + cy  (= 2xy + cy)
    ld   [0x24], ac
    sub  [0x1A], ac
    bge  nb_51
    and  0x7F, ac
    ld   ac, [0x20]
    ld   [0x25], ac
    sub  [0x1B], ac
    dec
    bra  sd_52
nb_51:
    ld   ac, [0x20]
    ld   [0x25], ac
    sub  [0x1B], ac
sd_52:
    ld   ac, [0x21]
    ld   [0x20], ac
    add  [0x28], ac
    bge  nc_53
    and  0x7F, ac
    ld   ac, [0x20]
    ld   [0x21], ac
    add  [0x29], ac
    inc
    bra  ad_54
nc_53:
    ld   ac, [0x20]
    ld   [0x21], ac
    add  [0x29], ac
ad_54:
    ld   ac, [0x21]
    ld   kernel3 >> 8, y
    jmp  kernel3

#addr 0x1100
kernel3:
    ; back to magnitude + sign, escape if |x'| or |y'| >= 2
    ld   [0x1F], ac
    blt  neg_55
    sub  4, ac
    bge  esc3
    ld   [0x1E], ac
    ld   ac, [0x10]
    ld   [0x1F], ac
    ld   ac, [0x11]
    clr  ac
    ld   ac, [0x12]
    bra  sm_58
neg_55:
    clr  ac                    ; magnitude = 0 - value
    sub  [0x1E], ac
    bge  nb_56
    and  0x7F, ac
    ld   ac, [0x10]
    clr  ac
    sub  [0x1F], ac
    dec
    bra  mh_57
nb_56:
    ld   ac, [0x10]
    clr  ac
    sub  [0x1F], ac
mh_57:
    ld   ac, [0x11]
    sub  4, ac
    bge  esc3
    ld   1, ac
    ld   ac, [0x12]
sm_58:
    ld   [0x21], ac
    blt  neg_59
    sub  4, ac
    bge  esc3
    ld   [0x20], ac
    ld   ac, [0x13]
    ld   [0x21], ac
    ld   ac, [0x14]
    clr  ac
    ld   ac, [0x15]
    bra  sm_62
neg_59:
    clr  ac                    ; magnitude = 0 - value
    sub  [0x20], ac
    bge  nb_60
    and  0x7F, ac
    ld   ac, [0x13]
    clr  ac
    sub  [0x21], ac
    dec
    bra  mh_61
nb_60:
    ld   ac, [0x13]
    clr  ac
    sub  [0x21], ac
mh_61:
    ld   ac, [0x14]
    sub  4, ac
    bge  esc3
    ld   1, ac
    ld   ac, [0x15]
sm_62:
    ld   [0x2A], ac
    dec
    ld   ac, [0x2A]
    beq  esc3                 ; never escaped: it = 0 -> black
    ld   iter >> 8, y
    jmp  iter
esc3:
    ld   escape >> 8, y
    jmp  escape

#addr 0x1F00
colors:    ; mode m at offset 64*m, index = iterations left, already
           ; shifted to the top of the byte for the pixel packing
    #d8 0x00, 0x80, 0x00, 0x80, 0x00, 0x80, 0x00, 0x80, 0x00, 0x80, 0x00, 0x80, 0x00, 0x80, 0x00, 0x80
    #d8 0x00, 0x80, 0x00, 0x80, 0x00, 0x80, 0x00, 0x80, 0x00, 0x80, 0x00, 0x80, 0x00, 0x80, 0x00, 0x80
    #d8 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
    #d8 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
    #d8 0x00, 0x40, 0xC0, 0x80, 0x40, 0xC0, 0x80, 0x40, 0xC0, 0x80, 0x40, 0xC0, 0x80, 0x40, 0xC0, 0x80
    #d8 0x40, 0xC0, 0x80, 0x40, 0xC0, 0x80, 0x40, 0xC0, 0x80, 0x40, 0xC0, 0x80, 0x40, 0xC0, 0x80, 0x40
    #d8 0xC0, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
    #d8 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
    #d8 0x00, 0x80, 0xF0, 0x70, 0xD0, 0x50, 0x90, 0x10, 0xB0, 0x30, 0xA0, 0x20, 0xE0, 0x60, 0xC0, 0x40
    #d8 0x40, 0x80, 0xF0, 0x70, 0xD0, 0x50, 0x90, 0x10, 0xB0, 0x30, 0xA0, 0x20, 0xE0, 0x60, 0xC0, 0x40
    #d8 0x40, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
    #d8 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
    #d8 0x00, 0x17, 0x1E, 0x1C, 0x19, 0x58, 0x98, 0xF8, 0xF0, 0xE8, 0xE1, 0xE4, 0xE6, 0xA7, 0x67, 0x07
    #d8 0x0F, 0x17, 0x1E, 0x1C, 0x19, 0x58, 0x98, 0xF8, 0xF0, 0xE8, 0xE1, 0xE4, 0xE6, 0xA7, 0x67, 0x07
    #d8 0x0F, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
    #d8 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00

; squares k*k/256, low limbs, page 0x20 + k/128, X = k%128
#addr 0x2000
    #d8 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x01, 0x01, 0x01, 0x01
    #d8 0x01, 0x01, 0x01, 0x01, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x03, 0x03, 0x03, 0x03, 0x04, 0x04
